[
  {
    "name": "theme_info",
    "theme_name": "Velantra Quiet Luxury",
    "theme_version": "1.0.0",
    "theme_author": "Velantra",
    "theme_documentation_url": "https://help.shopify.com/en/manual/online-store/themes",
    "theme_support_url": "https://velantrafashion.com/pages/contact"
  },
  {
    "name": "Colors",
    "settings": [
      {
        "type": "color",
        "id": "color_background",
        "label": "Page background",
        "default": "#fdfdfd"
      },
      {
        "type": "color",
        "id": "color_text",
        "label": "Text",
        "default": "#2a2a2a"
      },
      {
        "type": "color",
        "id": "color_line",
        "label": "Dividers",
        "default": "#d1d1cd"
      },
      {
        "type": "color",
        "id": "color_muted",
        "label": "Secondary text",
        "default": "#686861"
      },
      {
        "type": "color",
        "id": "studio_background",
        "label": "Studio background",
        "default": "#ffffff"
      }
    ]
  },
  {
    "name": "Typography",
    "settings": [
      {
        "type": "checkbox",
        "id": "custom_fonts",
        "label": "Use custom fonts",
        "default": false
      },
      {
        "type": "font_picker",
        "id": "body_font",
        "label": "Body font",
        "default": "montserrat_n4"
      },
      {
        "type": "font_picker",
        "id": "heading_font",
        "label": "Heading font",
        "default": "cormorant_garamond_n4"
      }
    ]
  },
  {
    "name": "Layout and brand",
    "settings": [
      {
        "type": "checkbox",
        "id": "transparent_header",
        "label": "Transparent homepage header",
        "default": true
      },
      {
        "type": "range",
        "id": "page_width",
        "label": "Page width",
        "min": 1000,
        "max": 2000,
        "step": 50,
        "unit": "px",
        "default": 1600
      },
      {
        "type": "range",
        "id": "section_spacing",
        "label": "Section spacing",
        "min": 40,
        "max": 160,
        "step": 8,
        "unit": "px",
        "default": 96
      },
      {
        "type": "image_picker",
        "id": "favicon",
        "label": "Favicon"
      },
      {
        "type": "url",
        "id": "instagram",
        "label": "Instagram URL"
      },
      {
        "type": "url",
        "id": "facebook",
        "label": "Facebook URL"
      }
    ]
  }
]

{
  "sections": {
    "hero": {
      "type": "hero-film",
      "settings": {}
    },
    "philosophy": {
      "type": "editorial-text",
      "settings": {
        "eyebrow": "Philosophy",
        "heading": "LUXURY, WITHOUT THE LOGO",
        "text": "<p>Some pieces speak for themselves.</p><p>In the curve of a handle, the warmth of leather, and the way a bag becomes part of your day.<br>Velantra is a collection for that feeling. Beautiful to carry. Entirely your own.</p>"
      }
    },
    "triptych": {
      "type": "image-gallery",
      "settings": {
        "columns": 3,
        "ratio": "4/5"
      },
      "blocks": {
        "image1": {
          "type": "image",
          "settings": {
            "default_asset": "vivienne-editorial-1.jpg",
            "alt": "The Vivienne, a study in everyday elegance",
            "link": "/products/velantra-vivienne"
          }
        },
        "image2": {
          "type": "image",
          "settings": {
            "default_asset": "vivienne-editorial-2.jpg",
            "alt": "The Vivienne, a study in everyday elegance",
            "link": "/products/velantra-vivienne"
          }
        },
        "image3": {
          "type": "image",
          "settings": {
            "default_asset": "vivienne-editorial-3.jpg",
            "alt": "The Vivienne, a study in everyday elegance",
            "link": "/products/velantra-vivienne"
          }
        }
      },
      "block_order": [
        "image1",
        "image2",
        "image3"
      ]
    },
    "atelier": {
      "type": "editorial-text",
      "settings": {
        "eyebrow": "The Vivienne",
        "heading": "A QUIET PRESENCE",
        "text": "<p>Vegetable-tanned leather. A belted brass closure. A silhouette with a life of its own.</p><p>Our bestselling top handle bag, made for everything the day holds.</p>",
        "label": "Discover The Vivienne",
        "link": "/products/velantra-vivienne"
      }
    },
    "collection": {
      "type": "featured-collection",
      "settings": {
        "heading": "THE EVERYDAY COLLECTION",
        "columns": 2,
        "limit": 2
      }
    },
    "detail": {
      "type": "image-with-text",
      "settings": {
        "default_asset": "vivienne-detail.jpg",
        "eyebrow": "Our approach",
        "heading": "BEAUTY IN THE EVERYDAY",
        "text": "<p>The bag you carry should feel like you.</p><p>We focus on the things you touch and use: tactile materials, thoughtful proportions, and details that earn their place.</p><p>With the Vivienne, one vegetable-tanned leather runs through every panel, from the body to the corners, gussets, and piping.</p>"
      },
      "blocks": {
        "material": {
          "type": "value",
          "settings": {
            "label": "The Vivienne",
            "value": "Vegetable-tanned leather"
          }
        },
        "hardware": {
          "type": "value",
          "settings": {
            "label": "The detail",
            "value": "Belted brass closure"
          }
        },
        "signature": {
          "type": "value",
          "settings": {
            "label": "The signature",
            "value": "Luxury without the logo"
          }
        }
      },
      "block_order": [
        "material",
        "hardware",
        "signature"
      ]
    },
    "closing": {
      "type": "editorial-text",
      "settings": {
        "eyebrow": "The edit",
        "heading": "WELL CARRIED",
        "text": "<p>For the everyday, and the days you remember.</p>",
        "label": "Explore the collection",
        "link": "/collections/all"
      }
    },
    "wide": {
      "type": "image-gallery",
      "settings": {
        "columns": 1,
        "ratio": "21/9",
        "gap": 0,
        "padding": 0
      },
      "blocks": {
        "image": {
          "type": "image",
          "settings": {
            "default_asset": "vivienne-studio-wide.jpg",
            "alt": "The Vivienne in the studio",
            "link": "/products/velantra-vivienne"
          }
        }
      },
      "block_order": [
        "image"
      ]
    },
    "macro": {
      "type": "detail-film",
      "settings": {
        "description": "A closer look at Vivienne leather and hardware"
      }
    }
  },
  "order": [
    "hero",
    "philosophy",
    "triptych",
    "wide",
    "atelier",
    "collection",
    "macro",
    "detail",
    "closing"
  ]
}
